def get_protein_data(cancer_type: str, gene_symbol: str) -> Optional[pd.DataFrame]:
    """
    Get protein abundance data for a specific gene from CPTAC.

    Args:
        cancer_type: Cancer type abbreviation
        gene_symbol: Gene symbol to query

    Returns:
        DataFrame with protein abundance and sample type (Tumor/Normal)
    """
    try:
        dataset = load_cptac_dataset(cancer_type)
        if dataset is None:
            return None

        # Get proteomics data - try different sources in priority order
        # BCM is prioritized as it's more standardized across cancer types
        # UMICH as backup due to its proteomics specialization
        proteomics = None
        sources_to_try = ['bcm', 'umich', 'broad', 'washu', 'mssm']

        for source in sources_to_try:
            try:
                proteomics = dataset.get_proteomics(source=source)
                break
            except:
                continue

        if proteomics is None or proteomics.empty:
            return None

        # Find gene column - handle both string and tuple column names
        gene_column = None

        # 1. Try exact match
        if gene_symbol in proteomics.columns:
            gene_column = gene_symbol
        else:
            # 2. Handle tuple column names (gene_symbol, protein_id)
            for col in proteomics.columns:
                if isinstance(col, tuple):
                    # For tuple columns, check the first element (gene symbol)
                    if col[0].upper() == gene_symbol.upper():
                        gene_column = col
                        break
                elif isinstance(col, str):
                    # For string columns, try case-insensitive match
                    if col.upper() == gene_symbol.upper():
                        gene_column = col
                        break

            # 3. Try partial match (for genes with suffixes like isoforms)
            if gene_column is None:
                for col in proteomics.columns:
                    if isinstance(col, tuple):
                        # Check if gene symbol is in the tuple's first element
                        if gene_symbol.upper() in col[0].upper():
                            gene_column = col
                            break
                    elif isinstance(col, str):
                        # Check if gene symbol is in the string column name
                        if gene_symbol.upper() in col.upper():
                            gene_column = col
                            break

        if gene_column is None:
            return None

        # Extract gene data
        protein_data = proteomics[[gene_column]].copy()
        protein_data.columns = ['abundance']

        # Get clinical data for sample types
        clinical = None
        try:
            clinical = dataset.get_clinical()
        except:
            try:
                clinical = dataset.get_clinical(tissue_type='both')
            except:
                pass

        # Add sample type from clinical data or infer from index
        if clinical is not None and not clinical.empty:
            # Different datasets may have different column names for sample type
            sample_type_col = None
            for col in ['Sample_Type', 'sample_type', 'tumor_normal', 'Sample_Status']:
                if col in clinical.columns:
                    sample_type_col = col
                    break

            if sample_type_col is not None:
                # Align indices
                common_samples = protein_data.index.intersection(clinical.index)
                protein_data = protein_data.loc[common_samples]
                protein_data['sample_type'] = clinical.loc[common_samples, sample_type_col]

                # Standardize sample type labels
                protein_data['sample_type'] = protein_data['sample_type'].replace({
                    'Tumor': 'Tumor',
                    'tumor': 'Tumor',
                    'Primary Tumor': 'Tumor',
                    'Normal': 'Normal',
                    'normal': 'Normal',
                    'Solid Tissue Normal': 'Normal',
                    'NAT': 'Normal',  # Normal Adjacent Tissue
                })

                # Filter to only Tumor and Normal samples
                protein_data = protein_data[protein_data['sample_type'].isin(['Tumor', 'Normal'])]
            else:
                # Infer from sample IDs (common CPTAC pattern)
                protein_data['sample_type'] = protein_data.index.to_series().apply(
                    lambda x: 'Normal' if 'Normal' in str(x) or 'NAT' in str(x) or '.N' in str(x) 
                             else 'Tumor'
                )
        else:
            # If no clinical data, infer from sample IDs
            protein_data['sample_type'] = protein_data.index.to_series().apply(
                lambda x: 'Normal' if 'Normal' in str(x) or 'NAT' in str(x) or '.N' in str(x) 
                         else 'Tumor'
            )

        # Remove rows with NaN abundance
        protein_data = protein_data.dropna(subset=['abundance'])

        # Add cancer type
        protein_data['cancer_type'] = cancer_type

        return protein_data.reset_index(drop=True) if not protein_data.empty else None

    except Exception:
        return None


