logger = logging.getLogger(__name__)


def detect_cpu_count() -> int:
    """Return the number of CPU cores usable by this process.

    Resolution order:
        1. ``KRAKEN_THREADS`` env var, if it parses to a positive int.
        2. ``os.sched_getaffinity(0)`` on Linux (honors cgroups/taskset).
        3. ``os.cpu_count()`` as a portable fallback.
        4. ``1`` if everything above fails.

    Using ``sched_getaffinity`` matters on container/orchestrator hosts
    where ``cpu_count()`` reports the bare-metal core count rather than
    the slice the process was actually scheduled onto.
    """
    env_override = os.environ.get("KRAKEN_THREADS")
    if env_override:
        try:
            n = int(env_override)
            if n >= 1:
                return n
        except ValueError:
            logger.warning(
                f"Ignoring invalid KRAKEN_THREADS={env_override!r}; expected positive integer"
            )

    try:
        return len(os.sched_getaffinity(0))
    except AttributeError:
        # sched_getaffinity is Linux-only; macOS/Windows take this path.
        return os.cpu_count() or 1


def resolve_thread_count(configured: Optional[int], reserve: int = 1) -> int:
    """Resolve the effective worker-thread count.

    An explicit ``configured`` value always wins so users can pin threads
    for reproducibility or shared-host courtesy. When unset (``None``),
    we auto-detect and hold back ``reserve`` cores so the OS/UI stays
    responsive on workstations.
    """
    if configured is not None and configured >= 1:
        return int(configured)
    available = detect_cpu_count()
    return max(1, available - max(0, reserve))

